47	// assertReplacementBaseUnchanged 校验失败登记整次回滚：
48	// 查询仍只有 v1、v3，v1 未被提前截断、没有失败版本留下的替代关系，
49	// v3 继续保持原来的持续有效区间。
50	func assertReplacementBaseUnchanged(t *testing.T, b *Book) {
51		t.Helper()
52		views, err := b.ItemVersions("seat")
53		if err != nil {
54			t.Fatal(err)
55		}
56		if len(views) != 2 {
57			t.Fatalf("失败登记后应仍只有两个版本，got %d: %+v", len(views), views)
58		}
59		old, follow := views[0], views[1]
60		if old.VersionID != "seat-v1" || follow.VersionID != "seat-v3" {
