	}
	if got != first {
		t.Fatalf("历史报价被丙版登记改写: %+v -> %+v", first, got)
	}
	if got.Request != req || got.UnitPrice != 180 || got.Total != 720 ||
		!got.AcceptedAt.Equal(acceptedAt) {
		t.Fatalf("历史报价未保留原请求/金额/受理时刻: %+v", got)
	}

