func newChainedBook(t *testing.T, start time.Time) (*Book, func(time.Time)) {
	t.Helper()
	now, setNow := fixedClock(start)
	b := NewBook(WithClock(now))
	registerChainV1V2(t, b)
	registerChainV3(t, b)
	return b, setNow
